        { step: 4, title: "\u7D50\u679C\u3092\u30B3\u30D4\u30FC", desc: "\u5909\u63DB\u3055\u308C\u305F\u6587\u5B57\u5217\u3092\u30EF\u30F3\u30AF\u30EA\u30C3\u30AF\u3067\u30AF\u30EA\u30C3\u30D7\u30DC\u30FC\u30C9\u306B\u30B3\u30D4\u30FC\u3057\u3066\u5229\u7528\u3057\u307E\u3059\u3002" }
