        { q: "URL\u30A8\u30F3\u30B3\u30FC\u30C9\u3092\u884C\u3048\u3070SQL\u30A4\u30F3\u30B8\u30A7\u30AF\u30B7\u30E7\u30F3\u306A\u3069\u306E\u653B\u6483\u3092\u9632\u3052\u307E\u3059\u304B\uFF1F", a: "\u3044\u3044\u3048\u3002URL\u30A8\u30F3\u30B3\u30FC\u30C9\u306F\u30C7\u30FC\u30BF\u4F1D\u9001\u306E\u305F\u3081\u306E\u30D5\u30A9\u30FC\u30DE\u30C3\u30C8\u5909\u63DB\u3067\u3042\u308A\u3001\u30BB\u30AD\u30E5\u30EA\u30C6\u30A3\u5BFE\u7B56\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002\u30B5\u30FC\u30D0\u30FC\u5074\u3067\u306E\u9069\u5207\u306A\u30B5\u30CB\u30BF\u30A4\u30BA\u51E6\u7406\u304C\u4E0D\u53EF\u6B20\u3067\u3059\u3002" }
