        { step: 4, title: "\u7D50\u679C\u3092\u30B3\u30D4\u30FC", desc: "\u6574\u5F62\u3055\u308C\u305FJSON\u30C7\u30FC\u30BF\u3092\u30AF\u30EA\u30C3\u30D7\u30DC\u30FC\u30C9\u306B\u30B3\u30D4\u30FC\u3057\u3066\u5229\u7528\u3057\u307E\u3059\u3002" }
