      { id: "hash-generator", name: "Hash Generator", desc: { en: "Calculate HMAC and SHA-256 digests used in token signing.", ko: "\uD1A0\uD070 \uC11C\uBA85\uC5D0 \uC0AC\uC6A9\uB418\uB294 SHA-256 \uBC0F \uD574\uC2DC \uB2E4\uC774\uC81C\uC2A4\uD2B8\uB97C \uACC4\uC0B0\uD569\uB2C8\uB2E4.", ja: "\u30C8\u30FC\u30AF\u30F3\u7F72\u540D\u306B\u7528\u3044\u3089\u308C\u308B\u6697\u53F7\u5B66\u7684\u30CF\u30C3\u30B7\u30E5\u5024\u3092\u8A08\u7B97\u3057\u307E\u3059\u3002" }, icon: "Hash" }
