        { title: "2\u8981\u7D20\u8A8D\u8A3C\uFF08TOTP\uFF09\u306E\u691C\u8A3C", desc: "\u8A8D\u8A3C\u30A2\u30D7\u30EA\u306B\u767B\u9332\u3059\u308B\u305F\u3081\u306E\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u7528QR\u30B3\u30FC\u30C9\u3092\u751F\u6210\u30FB\u30C6\u30B9\u30C8\u3057\u307E\u3059\u3002" }
