        "\u30D6\u30E9\u30A6\u30B6\u5B8C\u7D50\u306E\u51E6\u7406\u306B\u3088\u308A\u3001\u793E\u5185\u975E\u516C\u958BAPI\u306E\u4ED5\u69D8\u60C5\u5831\u3082\u5B89\u5168\u306B\u8A2D\u8A08\u3067\u304D\u307E\u3059\u3002"
