// src/data/toolsContent/index.ts
var allToolsContent = [
  ...dataTools,
  ...securityTools,
  ...utilityTools,
  ...aiTools
];
var toolsContentMap = allToolsContent.reduce((acc, tool) => {
  acc[tool.id] = tool;
  return acc;
}, {});
function getToolContent(id) {
  return toolsContentMap[id];
}
